// Regenerate: node scripts/bundle-migrations.js
//
// Applied in filename order; each id is recorded in schema_migrations so a
// re-run is a no-op. Every migration must be idempotent anyway
// (CREATE TABLE IF NOT EXISTS / ALTER TABLE … ADD COLUMN), because a
// database created before this runner existed has no schema_migrations
// row for migrations whose effects it already carries.

export const MIGRATIONS = [
  { id: "001_social_posts", sql: "-- ============================================================================\n-- Social distribution queue\n-- ============================================================================\n-- One row per (blog post, channel) publication attempt. Publishing to an\n-- external network is not transactional with the blog write, so it gets\n-- its own durable job: the blog publish enqueues, and the cron drains.\n-- Without this, a dropped connection or a Facebook 5xx silently loses the\n-- post — the old fire-and-forget waitUntil() only wrote an audit line.\n--\n--   status: pending | publishing | published | failed | skipped\n--   next_attempt_at: unix seconds; exponential backoff between attempts\n--   needs_reconnect: 1 when the failure is a credential problem (bad or\n--     expired token, missing permission). Retrying is pointless until a\n--     human reconnects the channel, so the UI surfaces it as an action.\nCREATE TABLE IF NOT EXISTS social_posts (\n  id              TEXT PRIMARY KEY,\n  project_id      TEXT,\n  blog_post_id    TEXT NOT NULL,\n  channel         TEXT NOT NULL DEFAULT 'facebook',\n  status          TEXT NOT NULL DEFAULT 'pending',\n  attempts        INTEGER NOT NULL DEFAULT 0,\n  max_attempts    INTEGER NOT NULL DEFAULT 5,\n  next_attempt_at INTEGER NOT NULL,\n  external_id     TEXT,\n  external_url    TEXT,\n  error           TEXT,\n  needs_reconnect INTEGER NOT NULL DEFAULT 0,\n  created_at      INTEGER NOT NULL,\n  updated_at      INTEGER NOT NULL,\n  published_at    INTEGER\n);\n\n-- Idempotency: a retried blog publish must not enqueue a second time.\nCREATE UNIQUE INDEX IF NOT EXISTS idx_social_post_channel\n  ON social_posts(blog_post_id, channel);\n\n-- The drain query: due jobs, oldest first.\nCREATE INDEX IF NOT EXISTS idx_social_due\n  ON social_posts(status, next_attempt_at);\n\nCREATE INDEX IF NOT EXISTS idx_social_project\n  ON social_posts(project_id, created_at DESC);" },
  { id: "002_project_scoped_aliases", sql: "-- 002: project-scoped internal-link aliases.\n--\n-- The problem: site_aliases was global. buildAliasMap() returned EVERY row to\n-- every project, so the AI writing for project A was told it could link to\n-- project B's pages, and the sanitiser would happily expand those names into\n-- A's article. A cross-tenant content leak, not just a cosmetic one.\n--\n-- Why the table is rebuilt rather than ALTERed: the legacy table has\n-- `name TEXT PRIMARY KEY`, so only one row per name can exist in the whole\n-- database. Two projects could not each own a `login` alias. SQLite cannot\n-- change a primary key in place, so the table is recreated.\n--\n-- Nothing is dropped. The legacy table is RENAMED to site_aliases_legacy and\n-- left in place as a recovery copy; all rows are copied forward first.\n--\n-- project_id uses '' (not NULL) for \"global\". SQLite treats NULLs as distinct\n-- in a unique index, so a NULL-scoped row could be inserted twice and\n-- `ON CONFLICT(project_id, name)` would never fire for it. The empty string\n-- keeps the constraint meaningful.\n--\n-- This runs on fresh installs too — schema/init.sql still declares the legacy\n-- shape, so every database takes the same upgrade path and the migration is\n-- exercised by every install rather than only by old ones.\n\nALTER TABLE site_aliases RENAME TO site_aliases_legacy;\n\nCREATE TABLE IF NOT EXISTS site_aliases (\n  id          TEXT PRIMARY KEY,\n  project_id  TEXT NOT NULL DEFAULT '',   -- '' = shared/legacy\n  name        TEXT NOT NULL,\n  url         TEXT NOT NULL,\n  description TEXT,\n  kind        TEXT NOT NULL DEFAULT 'manual',  -- manual | sitemap\n  created_at  INTEGER NOT NULL,\n  updated_at  INTEGER NOT NULL\n);\n\n-- Scope + name is the identity. Composite so each project owns its own\n-- vocabulary; '' still allows one shared row per name.\nCREATE UNIQUE INDEX IF NOT EXISTS idx_site_aliases_scope\n  ON site_aliases(project_id, name);\n\nCREATE INDEX IF NOT EXISTS idx_site_aliases_project\n  ON site_aliases(project_id, kind);\n\n-- Copy every legacy row forward as global (''). Existing installs keep\n-- working exactly as before until an operator re-syncs per project.\nINSERT INTO site_aliases (id, project_id, name, url, description, kind, created_at, updated_at)\n  SELECT lower(hex(randomblob(16))), '', name, url, description, kind, created_at, updated_at\n    FROM site_aliases_legacy;" },
  { id: "003_product_events", sql: "-- 003: product events.\n--\n-- Deliberately narrow. Most of what a product owner wants to know is already\n-- derivable from the data the product writes anyway:\n--\n--   activation      projects.created_at → first blog_posts.published_at\n--   retention       blog_posts.published_at grouped by project and week\n--   activity        posts per week, per project\n--\n-- Deriving those is strictly better than logging them: it is retroactive\n-- (no gap before instrumentation existed), it cannot drift from the real\n-- state, and it costs no writes on the hot path.\n--\n-- This table exists only for the things that are NOT derivable — the moments\n-- where someone chose to do something and we would otherwise have no record\n-- of the choice: which setup step they abandoned, whether they tried to\n-- connect a channel and it failed, that kind of thing. That is the\n-- information needed to explain a drop-off, not just measure it.\n--\n-- Writes are fire-and-forget: a failure to record an event must never fail\n-- the user action it describes.\n\nCREATE TABLE IF NOT EXISTS product_events (\n  id         TEXT PRIMARY KEY,\n  event      TEXT NOT NULL,\n  project_id TEXT,\n  user_id    TEXT,\n  props_json TEXT,\n  created_at INTEGER NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_product_events_name_time\n  ON product_events(event, created_at DESC);\n\nCREATE INDEX IF NOT EXISTS idx_product_events_project\n  ON product_events(project_id, created_at DESC);" },
  { id: "004_project_onboarding", sql: "-- 004: per-project onboarding state.\n--\n-- The bug this fixes: onboarding was tracked as `settings.onboarding_complete`,\n-- a GLOBAL row. The settings table has no project_id, so the first project that\n-- finished the wizard marked EVERY project complete — which is why a brand new\n-- account sailed straight past the setup step. The Brand DNA and schedule\n-- checks were read from the same global settings row for the same reason.\n--\n-- State now lives on the project itself.\n--\n-- Backfill: a project that already has Brand DNA AND calendar slots has, in\n-- fact, been set up, so it is marked complete. Without this every existing\n-- install would be dropped into the wizard on next login — correct per the\n-- letter of the rule, wrong for the operator, and it would have looked like\n-- the upgrade broke their site.\n--\n-- The guard (`onboarding_complete_at IS NULL`) keeps the statement idempotent.\n\nALTER TABLE projects ADD COLUMN onboarding_complete_at INTEGER;\n\nUPDATE projects\n   SET onboarding_complete_at = strftime('%s', 'now')\n WHERE onboarding_complete_at IS NULL\n   AND EXISTS (\n     SELECT 1 FROM project_brands b\n      WHERE b.project_id = projects.id\n        AND (b.business_type IS NOT NULL OR b.audience IS NOT NULL)\n   )\n   AND EXISTS (\n     SELECT 1 FROM content_calendar c\n      WHERE c.project_id = projects.id\n   );" },
  { id: "005_canonical_email", sql: "-- 005: canonical email, for duplicate detection.\n--\n-- Gmail ignores dots in the local part and treats `+tag` as a subaddress, so\n-- `g.u.l.a.g.i@gmail.com`, `gulagi+shop@gmail.com` and `gulagi@gmail.com` are\n-- one mailbox. Without this column the sign-up check compared raw strings and\n-- let the same person register unlimited accounts by adding dots.\n--\n-- `users.email` is UNCHANGED and remains the real address — the one that gets\n-- mailed. `email_canonical` is a comparison key only: collapsing is lossy, so\n-- it must never be used to send anything.\n--\n-- Backfill is deliberately CONSERVATIVE: `lower(email)` only. Expressing the\n-- dot/plus collapse in SQL here would be a second implementation of the same\n-- rule, free to drift from functions/_lib/email_rules.js — the exact failure\n-- that made three copies of the provider dispatch. `lower(email)` is already\n-- correct for every non-Google domain, and the Google rows are corrected by\n-- POST /api/admin/users/recanonicalize, which runs the same JS the app uses.\n--\n-- A wrong canonical only causes a MISSED duplicate (a second account gets\n-- created), never a lockout: existing users keep signing in with `email`.\n\nALTER TABLE users ADD COLUMN email_canonical TEXT;\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_users_email_canonical ON users(email_canonical);\n\nUPDATE users\n   SET email_canonical = lower(email)\n WHERE email_canonical IS NULL;" },
  { id: "006_domain_approval", sql: "-- 006: custom-domain approval queue.\n--\n-- Saving a domain used to go live immediately (and before that, to only\n-- touch D1 without ever attaching on Cloudflare). New flow: a tenant's\n-- save creates a PENDING request, a super_admin approves it on the Duyệt\n-- domain page, and only the approval attaches the hostname on Cloudflare\n-- and flips the live `custom_domain`.\n--\n-- `custom_domain` stays the live value routing reads; pending values never\n-- affect serving. `custom_domain_status` is pending | live | rejected, NULL\n-- when the project never requested.\n\nALTER TABLE projects ADD COLUMN pending_custom_domain TEXT;\nALTER TABLE projects ADD COLUMN custom_domain_status TEXT;\nALTER TABLE projects ADD COLUMN pending_requested_at INTEGER;" },
  { id: "007_video_jobs", sql: "-- 007: video jobs — 9:16 social videos rendered by the external\n-- HyperFrames agent (VPS with Chrome + FFmpeg; Workers can't render).\n--\n-- Flow: a published blog post gets ONE video job. The off-platform\n-- agent polls /api/admin/video/claim, renders (LLM script + edge-tts\n-- voiceover + HyperFrames), then POSTs the MP4 to\n-- /api/admin/video/deliver which stores it in R2 and flips status.\n--\n--   status: pending | claimed | rendering | done | failed\n--   script: the AI-written voiceover script (JSON) — kept for reuse\n--           so a re-render never re-bills the LLM for the same post.\n--\n-- UNIQUE(blog_post_id) makes the claim path race-free: two agents\n-- claiming the same post cannot both INSERT.\n\nCREATE TABLE IF NOT EXISTS video_jobs (\n  id              TEXT PRIMARY KEY,\n  project_id      TEXT,\n  blog_post_id    TEXT NOT NULL,\n  slug            TEXT,\n  status          TEXT NOT NULL DEFAULT 'pending',  -- pending | claimed | rendering | done | failed\n  script          TEXT,                             -- AI voiceover script (JSON)\n  video_key       TEXT,                             -- R2 object key once done\n  error           TEXT,\n  attempts        INTEGER NOT NULL DEFAULT 0,\n  claimed_at      INTEGER,\n  created_at      INTEGER NOT NULL,\n  updated_at      INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_video_jobs_status ON video_jobs(status, updated_at DESC);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_video_jobs_post ON video_jobs(blog_post_id);" },
  { id: "008_video_brand", sql: "-- 008: AI Video Post — brand kit columns + business video jobs.\n--\n-- The video agent composes every clip from a per-project brand kit\n-- (the frame.md idea): accent colour, tagline, address, phone. Brand\n-- DNA (project_brands) supplies tone/audience/themes; these columns\n-- carry the physical brand tokens the composition template renders.\n--\n-- video_jobs.kind: 'post' (per blog post, the existing flow) or\n-- 'business' (one promo video per project, no blog post behind it —\n-- blog_post_id carries a 'project:<id>' sentinel so the UNIQUE index\n-- still holds without a table rebuild).\nALTER TABLE projects ADD COLUMN video_tagline TEXT;\nALTER TABLE projects ADD COLUMN brand_accent TEXT;\nALTER TABLE projects ADD COLUMN address TEXT;\nALTER TABLE projects ADD COLUMN phone TEXT;\nALTER TABLE video_jobs ADD COLUMN kind TEXT NOT NULL DEFAULT 'post';  -- post | business" },
  { id: "009_video_website", sql: "-- 009: website promo videos + source tracking.\n--\n-- kind='website' jobs render a promo from a live URL: the agent\n-- screenshots the site's pages and scrapes its text as storyboard\n-- material. `source_url` records the URL the job was created from\n-- (blog_post_id carries a 'url:<id>' sentinel for the UNIQUE index).\nALTER TABLE video_jobs ADD COLUMN source_url TEXT;" },
  { id: "010_social_channels", sql: "-- ============================================================================\n-- 010: multi-channel social distribution (project_channels).\n--\n-- Before this table a project had exactly ONE external channel: the\n-- publisher_type column of project_publishing_configs. \"Post to Facebook\n-- AND Instagram AND X\" was impossible — the operator made N manual\n-- round-trips per article.\n--\n-- One row per (project, channel). Enabled channels are fanned out at blog\n-- publish time into social_posts, which already carries retry, backoff and\n-- needs_reconnect machinery — nothing about the queue changes.\n--\n-- Legacy: project_publishing_configs.publisher_type stays the source of\n-- truth for projects with no rows here. listEnabledChannels() in\n-- functions/_lib/channels.js falls back to it, so existing installs keep\n-- publishing to their single channel without any operator action, and the\n-- first channel card they touch migrates them onto rows.\n--\n-- config_json holds per-channel NON-secret settings (page_id, ig_user_id,\n-- threads_user_id, hashtags, message template). Secrets (tokens) never go\n-- here — this table is plaintext; they live in the vault under\n--   FACEBOOK_PAGE_TOKEN__<pid>   (shared by facebook + instagram)\n--   THREADS_TOKEN__<pid>\n--   X_API_KEY__<pid> / X_API_SECRET__<pid>\n--   X_ACCESS_TOKEN__<pid> / X_ACCESS_SECRET__<pid>\n\nCREATE TABLE IF NOT EXISTS project_channels (\n  id           TEXT PRIMARY KEY,\n  project_id   TEXT NOT NULL,\n  channel      TEXT NOT NULL,\n  enabled      INTEGER NOT NULL DEFAULT 1,\n  config_json  TEXT NOT NULL DEFAULT '{}',\n  connected_at INTEGER,\n  created_at   INTEGER NOT NULL,\n  updated_at   INTEGER NOT NULL\n);\n\n-- Identity: one row per (project, channel). A retried publish or a double\n-- save must not create a second row — upsert paths key on this index.\nCREATE UNIQUE INDEX IF NOT EXISTS idx_project_channels_unique\n  ON project_channels(project_id, channel);\n\nCREATE INDEX IF NOT EXISTS idx_project_channels_project\n  ON project_channels(project_id, enabled);" },
  { id: "011_video_templates", sql: "-- 011: user-chosen video templates + presenter photo.\n--\n-- The admin wizard lets the operator pick a render template and a\n-- duration per video job instead of leaving the choice to the agent.\n-- video_jobs.template carries the catalog id (NULL = 'auto', the engine\n-- picks); video_jobs.duration is the requested seconds (NULL = template\n-- default). Both are plain job-payload fields the claim hands to the\n-- agent — the platform never renders.\n--\n-- projects.presenter_name / presenter_image_url hold the talking-head\n-- identity that presenter templates (news_anchor) draw. The image is an\n-- R2 object served through /image/, stored as a relative path like\n-- logo_url; claim absolutizes it for the off-platform agent.\n--\n-- The statements also live in schema/init.sql — the baseline runner\n-- tolerates `duplicate column name`, so old and new DBs converge.\n\nALTER TABLE video_jobs ADD COLUMN template TEXT;\nALTER TABLE video_jobs ADD COLUMN duration INTEGER;\nALTER TABLE projects ADD COLUMN presenter_name TEXT;\nALTER TABLE projects ADD COLUMN presenter_image_url TEXT;" },
];
